import net.fabricmc.fabric.api.client.gametest.v1.*;import net.fabricmc.fabric.api.client.gametest.v1.context.*;import net.minecraft.client.model.*;import net.minecraft.client.model.geom.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.world.entity.*;
import io.github.r3neer.scalebrews.client.mixin.ModelPartAccess;import io.github.r3neer.scalebrews.collision.api.spi.PoseEngine;import io.github.r3neer.scalebrews.collision.pose.NumericPoseProgram;import io.github.r3neer.scalebrews.collision.geometry.*;
public final class S58AdversarialCompoundProof implements FabricClientGameTest {
static void check(boolean v,String why){if(!v)throw new AssertionError("S58 ADV "+why);}
static boolean cornerMatch(Vector3f v, net.minecraft.world.phys.Vec3 p, net.minecraft.world.phys.AABB box, Matrix4f nativeMatrix, Matrix4f commonMatrix){
 if(v.distanceSquared((float)p.x,(float)p.y,(float)p.z)<2e-10)return true;
 double[] radius={Math.max(Math.abs(box.minX),Math.abs(box.maxX)),Math.max(Math.abs(box.minY),Math.abs(box.maxY)),Math.max(Math.abs(box.minZ),Math.abs(box.maxZ))};
 float[] n=nativeMatrix.get(new float[16]),c=commonMatrix.get(new float[16]),actual={v.x,v.y,v.z},candidate={(float)p.x,(float)p.y,(float)p.z};
 for(int axis=0;axis<3;axis++){double error=Math.abs((double)n[12+axis]-c[12+axis])+Math.max(Math.ulp(actual[axis]),Math.ulp(candidate[axis]));for(int col=0;col<3;col++)error+=Math.abs((double)n[col*4+axis]-c[col*4+axis])*radius[col];if(Math.abs((double)actual[axis]-candidate[axis])>error)return false;}
 return true;
}
static List<Field> partFields(Object model){var out=new ArrayList<Field>();for(var c=model.getClass();c!=Model.class;c=c.getSuperclass())for(var f:c.getDeclaredFields())if(f.getType()==ModelPart.class&&!Modifier.isStatic(f.getModifiers())){f.setAccessible(true);out.add(f);}out.sort(Comparator.comparing(f->f.getDeclaringClass().getName()+"/"+f.getName()));return out;}
@SuppressWarnings({"rawtypes","unchecked"})public void runTest(ClientGameTestContext context){try{OriginalLinearPosePreparation.inspect(null);throw new AssertionError("off-thread admitted");}catch(IllegalStateException expected){}var world=context.worldBuilder().create();try{context.runOnClient(mc->{try{
var entity=EntityTypes.SHEEP.create(mc.level,EntitySpawnReason.COMMAND);var renderer=(LivingEntityRenderer)mc.getEntityRenderDispatcher().getRenderer(entity);var models=List.of((EntityModel)renderer.getModel(),new net.minecraft.client.model.animal.sheep.SheepFurModel(mc.getEntityModels().bakeLayer(ModelLayers.SHEEP_WOOL)));var report=new ArrayList<Object>();int matrices=0,cubes=0,samples=0;StringBuilder svg=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"900\" height=\"600\"><rect width=\"900\" height=\"600\" fill=\"white\"/>");int picture=0;
for(var model:models){Object nativeState=renderer.createRenderState();var root=model.root();var parts=S55AdversarialGeometryProof.parts(root);var originalInitial=new IdentityHashMap<ModelPart,PartPose>();var originalCurrent=new IdentityHashMap<ModelPart,PartPose>();var flags=new IdentityHashMap<ModelPart,boolean[]>();int pi=0;for(var p:parts.values()){originalInitial.put(p,p.getInitialPose());originalCurrent.put(p,S55AdversarialGeometryProof.current(p));flags.put(p,new boolean[]{p.visible,p.skipDraw});float f=++pi*.075f;p.setInitialPose(new PartPose(f,-f*.5f,f*.3f,.2f*f,-.7f*f,.3f*f,-.9f,1.2f,.8f));p.loadPose(new PartPose(1,2,3,.7f,.4f,-.3f,2,3,4));p.visible=false;p.skipDraw=true;}
var fields=partFields(model);check(fields.size()>=2,"native alias field foundation");Field alias=fields.stream().filter(f->f.getName().equals("head")).findFirst().orElseThrow(),destination=fields.stream().filter(f->f.getName().equals("leftFrontLeg")).findFirst().orElseThrow();Object savedAlias=alias.get(model);var normalMatrices=new HashMap<Integer,Map<String,Matrix4f>>();boolean aliasChanged=false;
try{for(int variant=0;variant<2;variant++){if(variant==1)alias.set(model,destination.get(model));String before=S55AdversarialGeometryProof.state(root);var fieldBefore=new ArrayList<Object>();for(var f:fields)fieldBefore.add(f.get(model));var preparedResult=OriginalLinearPosePreparation.inspect(model);check(preparedResult.admitted(),"original compile rejected "+preparedResult.absence());var prepared=preparedResult.prepared();check(before.equals(S55AdversarialGeometryProof.state(root)),"compiler changed current9/initial/flags/tree");for(int i=0;i<fields.size();i++)check(fields.get(i).get(model)==fieldBefore.get(i),"compiler changed field relation");check(!OriginalResetPosePreparation.inspect(model).admitted(),"reset-only API relaxed");check(!OriginalResetGeometryPreparation.inspect(model).admitted(),"reset export API relaxed");check(prepared.equals(OriginalLinearPosePreparation.inspect(model).prepared()),"repeat compilation identity drift");var program=prepared.program();var decoded=new Gson().fromJson(new Gson().toJson(program),NumericPoseProgram.class);check(decoded.equals(program),"program roundtrip drift");var bound=decoded.bind(decoded.geometry()).orElseThrow();check(bound.evaluate(null).isEmpty()&&bound.evaluate(new PoseEngine.Inputs(0,0,0,0,0,false)).isEmpty(),"invalid ordinary admitted");check(bound.evaluate(new PoseEngine.Inputs(0,0,0,0,0,true)).isEmpty(),"missing numeric fields admitted");var observations=new ArrayList<Object>();
for(int tick=0;tick<5;tick++){var input=new TreeMap<String,Float>();int ii=0;for(var source:prepared.inputs()){float value=(tick-2)*3.1415927f*(++ii+.13f);Class<?> owner=Class.forName(source.owner());var field=owner.getDeclaredField(source.name());field.setAccessible(true);field.setFloat(nativeState,value);input.put(source.channel(),value);}var values=new PoseEngine.Inputs(0,0,0,0,0,true,input);String unchanged=S55AdversarialGeometryProof.state(root);var replacement=bound.evaluate(values).orElseThrow();check(unchanged.equals(S55AdversarialGeometryProof.state(root)),"common evaluate changed shared model");var evaluated=decoded.geometry().transforms(replacement);((Model)model).setupAnim(nativeState);check(prepared.equals(OriginalLinearPosePreparation.inspect(model).prepared()),"animated recompilation identity drift");var reference=S55AdversarialGeometryProof.nativeMatrices(root);if(variant==0){var saved=new TreeMap<String,Matrix4f>();reference.forEach((id,m)->saved.put(id,new Matrix4f(m)));normalMatrices.put(tick,saved);}else if(tick!=2){for(var id:reference.keySet())if(!reference.get(id).equals(normalMatrices.get(tick).get(id),3e-6f))aliasChanged=true;}check(reference.keySet().equals(evaluated.keySet()),"joint identity membership");for(var id:reference.keySet()){check(reference.get(id).equals(evaluated.get(id),3e-6f),"native pose matrix differs "+id+" alias="+variant+" tick="+tick);matrices++;}
for(var piece:decoded.geometry().pieces()){var nativePart=parts.get(piece.part());int index=Integer.parseInt(piece.id().substring(piece.id().lastIndexOf("cube_")+5));var cube=((ModelPartAccess)(Object)nativePart).scalebrews$cubes().get(index);var originalVertices=new ArrayList<Vector3f>();for(var polygon:cube.polygons)for(var v:polygon.vertices())originalVertices.add(reference.get(piece.part()).transformPosition(new Vector3f(v.worldX(),v.worldY(),v.worldZ())));var box=ConvexBox.of(piece.box(),evaluated.get(piece.part()));for(var p:box.vertices())check(originalVertices.stream().anyMatch(v->cornerMatch(v,p,piece.box(),reference.get(piece.part()),evaluated.get(piece.part()))),"native cube corner differs "+piece.id()+" model="+model.getClass().getName()+" alias="+variant+" tick="+tick+" dto="+p+" native="+originalVertices+" box="+piece.box()+" minSq="+originalVertices.stream().mapToDouble(v->v.distanceSquared((float)p.x,(float)p.y,(float)p.z)).min().orElseThrow());for(var v:originalVertices)check(box.vertices().stream().anyMatch(p->cornerMatch(v,p,piece.box(),reference.get(piece.part()),evaluated.get(piece.part()))),"native cube vertex lost "+piece.id());cubes++;}
observations.add(Map.of("channels",input,"matrices",reference.entrySet().stream().collect(java.util.stream.Collectors.toMap(Map.Entry::getKey,e->ModelGeometry.values(e.getValue())))));samples++;
if(tick==1&&variant==0){var ref=new ArrayList<Vector3f>();var dto=new ArrayList<Vector3f>();for(var piece:decoded.geometry().pieces()){var part=parts.get(piece.part());var cube=((ModelPartAccess)(Object)part).scalebrews$cubes().get(Integer.parseInt(piece.id().substring(piece.id().lastIndexOf("cube_")+5)));for(var polygon:cube.polygons)for(var v:polygon.vertices())ref.add(reference.get(piece.part()).transformPosition(new Vector3f(v.worldX(),v.worldY(),v.worldZ())));for(var p:ConvexBox.of(piece.box(),evaluated.get(piece.part())).vertices())dto.add(new Vector3f((float)p.x,(float)p.y,(float)p.z));}svg.append(S55AdversarialGeometryProof.projection(ref,150,200+picture*250,"native compound pose")).append(S55AdversarialGeometryProof.projection(dto,550,200+picture*250,"common numeric pose"));picture++;}
}report.add(Map.of("program",program,"schema",prepared.inputs(),"alias",variant,"samples",observations));}check(aliasChanged,"alias holdout was vacuous against native pose");alias.set(model,savedAlias);}finally{alias.set(model,savedAlias);for(var p:parts.values()){p.setInitialPose(originalInitial.get(p));p.loadPose(originalCurrent.get(p));p.visible=flags.get(p)[0];p.skipDraw=flags.get(p)[1];}}}
check(!OriginalLinearPosePreparation.inspect(null).admitted(),"null admitted");var out=Path.of("s58-adversarial-snapshots");Files.createDirectories(out);Files.writeString(out.resolve("programs.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));Files.writeString(out.resolve("compound-pose.svg"),svg.append("</svg>"));System.out.println("S58_INDEPENDENT_COMPOUND_PASS models=2 aliases=2 samples="+samples+" matrices="+matrices+" cubes="+cubes+" oldResetAPI=strict");
}catch(Exception failure){throw new AssertionError(failure);}});}finally{world.close();}}
}
